/* Atlas faceted browsing PROTOTYPE, not referenced by production.
 * Reads approved per-destination JSON shards generated by atlas_facets_snapshot.py.
 * No map SDK, no geolocation, no third-party API, no innerHTML, no analytics.
 */
(() => {
  'use strict';
  const root = document.querySelector('[data-atlas-explore]');
  if (!root) return;

  const get = name => root.querySelector('[data-atlas-' + name + ']');
  const ui = {
    country: get('country'),
    destination: get('destination'),
    type: get('type'),
    work: get('work'),
    author: get('author'),
    relation: get('relation'),
    query: get('query'),
    results: get('results'),
    count: get('count'),
    previous: get('previous'),
    next: get('next'),
    page: get('page'),
    status: get('status'),
  };
  if (Object.values(ui).some(el => !el)) return;
  const retryButton = get('retry');

  const BASE = '/atlas-literario/facets/';
  const PAGE_SIZE = 30;
  const DATA_LIMIT = 500_000;
  let manifest = null;
  let current = null;
  let shownPage = 0;
  let selectionVersion = 0; // Descargas antiguas nunca sustituyen ciudad seleccionada ahora.
  const byCity = new Map();

  const normal = value => String(value ?? '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('es');

  const readJson = async url => {
    const response = await fetch(url, { credentials: 'same-origin' });
    if (!response.ok) throw new Error('HTTP ' + response.status);
    const raw = await response.text();
    if (raw.length > DATA_LIMIT) throw new Error('Fragmento de datos demasiado grande');
    return JSON.parse(raw);
  };

  const option = (value, label) => {
    const el = document.createElement('option');
    el.value = value;
    el.textContent = label;
    return el;
  };

  const fill = (el, entries, placeholder) => {
    const chosen = el.value;
    el.replaceChildren(option('', placeholder));
    for (const [id, label] of entries) el.append(option(id, label));
    el.value = entries.some(([id]) => id === chosen) ? chosen : '';
  };

  const message = text => { ui.status.textContent = text; };
  const pick = key => ui[key].value;

  const safeSlug = value => /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(value);

  const setHash = () => {
    const params = new URLSearchParams();
    for (const [short, key] of [['p', 'country'], ['d', 'destination'],
                                ['t', 'type'], ['b', 'work'], ['a', 'author'],
                                ['r', 'relation'], ['q', 'query']]) {
      if (pick(key)) params.set(short, pick(key));
    }
    history.replaceState(null, '', location.pathname + location.search +
      (params.toString() ? '#' + params.toString() : ''));
  };

  const openManifest = async () => {
    if (manifest) return manifest;
    manifest = await readJson(BASE + 'index.json');
    if (!Array.isArray(manifest.countries)) throw new Error('Manifiesto inválido');
    let displayNames = null;
    try { displayNames = new Intl.DisplayNames(['es'], { type: 'region' }); } catch (_) {}
    fill(ui.country, manifest.countries.map(c => [c.iso2,
      displayNames?.of(c.iso2) || c.iso2]), 'País');
    return manifest;
  };

  const availableCities = country =>
    (manifest?.countries ?? [])
      .find(c => c.iso2 === country)?.destinations ?? [];

  const loadCity = async slug => {
    if (!slug || !safeSlug(slug)) return null;
    if (!byCity.has(slug)) {
      byCity.set(slug, readJson(BASE + 'destinos/' + slug + '.json')
        .catch(error => { byCity.delete(slug); throw error; }));
    }
    return byCity.get(slug);
  };

  const setupRelationFacets = () => {
    const list = current?.places ?? [];
    const works = new Map(), authors = new Map(), relTypes = new Set(), types = new Set();
    for (const place of list) {
      types.add(place.type);
      for (const r of place.relations ?? []) {
        relTypes.add(r.relation);
        if (r.subject_type === 'work') works.set(r.subject_id, r.subject_name);
        if (r.subject_type === 'author') authors.set(r.subject_id, r.subject_name);
      }
    }
    const entries = map => [...map.entries()].sort((a, b) => a[1].localeCompare(b[1], 'es'));
    fill(ui.type, [...types].sort().map(x => [x, x.replaceAll('_', ' ')]), 'Tipo de lugar');
    fill(ui.work, entries(works), 'Obra');
    fill(ui.author, entries(authors), 'Autor');
    fill(ui.relation, [...relTypes].sort().map(x => [x, x.replaceAll('_', ' ')]), 'Tipo de vínculo');
  };

  const eligibleRows = () => {
    if (!current?.places) return [];
    const needle = normal(pick('query')).trim();
    return current.places.filter(p => {
      const relations = p.relations ?? [];
      if (pick('type') && p.type !== pick('type')) return false;
      if (pick('work') && !relations.some(r => r.subject_type === 'work' &&
                                                r.subject_id === pick('work'))) return false;
      if (pick('author') && !relations.some(r => r.subject_type === 'author' &&
                                                  r.subject_id === pick('author'))) return false;
      if (pick('relation') && !relations.some(r => r.relation === pick('relation'))) return false;
      return !needle || normal([p.name, ...relations.map(r => r.subject_name)].join(' ')).includes(needle);
    });
  };

  const render = () => {
    const filtered = eligibleRows();
    const pages = Math.ceil(filtered.length / PAGE_SIZE);
    shownPage = Math.min(shownPage, Math.max(0, pages - 1));
    const items = filtered.slice(shownPage * PAGE_SIZE, (shownPage + 1) * PAGE_SIZE);
    const list = document.createElement('ul');
    for (const p of items) {
      // Never trust a field from provider JSON as an arbitrary href.
      if (typeof p.url !== 'string' || !/^\/atlas-literario\/lugares\/[a-z0-9-]+\/$/.test(p.url)) continue;
      const li = document.createElement('li');
      const a = document.createElement('a');
      a.href = p.url;
      a.textContent = p.name;
      const meta = document.createElement('small');
      meta.textContent = p.type.replaceAll('_', ' ');
      li.append(a, document.createTextNode(' — '), meta);
      list.append(li);
    }
    ui.results.replaceChildren(list);
    ui.count.textContent = filtered.length + ' lugares';
    ui.page.textContent = pages ? 'Página ' + (shownPage + 1) + ' de ' + pages : '';
    ui.previous.disabled = shownPage === 0;
    ui.next.disabled = pages === 0 || shownPage >= pages - 1;
  };

  const refreshCountry = async () => {
    const cities = availableCities(pick('country'));
    fill(ui.destination, cities.map(d => [d.slug, d.name]), 'Ciudad o destino');
    await refreshCity();
  };

  const refreshCity = async () => {
    const version = ++selectionVersion;
    current = null;
    message('');
    const slug = pick('destination');
    const country = pick('country');
    if (slug && !availableCities(country).some(c => c.slug === slug)) {
      message('Destino no válido para el país seleccionado.');
      setupRelationFacets();
      render();
      return;
    }
    let data = null;
    try {
      data = slug ? await loadCity(slug) : null;
    } catch (error) {
      if (version !== selectionVersion) return; // Respuesta vieja, ya no interesa.
      throw error;
    }
    if (version !== selectionVersion) return;
    if (data && !Array.isArray(data.places)) throw new Error('Datos de destino no válidos');
    current = data;
    setupRelationFacets();
    shownPage = 0;
    render();
    setHash();
  };

  const handleError = error => {
    if (retryButton) retryButton.hidden = false;
    message('No se han podido cargar los lugares. Puedes navegar por los enlaces del directorio.');
    console.warn('Atlas facets preview:', error);
  };

  // Nothing fetched until a person opens/uses the controls, or a hash-linked view
  // needs hydration. On a normal landing page HTML content stands by itself.
  const start = async () => {
    try {
      await openManifest();
      const fromHash = new URLSearchParams(location.hash.slice(1));
      if (fromHash.has('p')) ui.country.value = fromHash.get('p') || '';
      await refreshCountry();
      if (fromHash.has('d')) {
        ui.destination.value = fromHash.get('d') || '';
        await refreshCity();
      }
      for (const [field, code] of [['type', 't'], ['work', 'b'], ['author', 'a'],
                                   ['relation', 'r'], ['query', 'q']]) {
        if (fromHash.has(code)) ui[field].value = fromHash.get(code) || '';
      }
      render();
    } catch (error) { handleError(error); }
  };
  let started = false;
  const boot = () => {
    if (started) return;
    started = true;
    void start();
  };
  root.addEventListener('focusin', boot, { once: true });
  root.addEventListener('pointerdown', boot, { once: true });
  if (location.hash.includes('d=')) boot();
  retryButton?.addEventListener('click', () => {
    retryButton.hidden = true;
    started = false;
    boot();
  });

  ui.country.addEventListener('change', () => {
    void refreshCountry().catch(handleError);
  });
  ui.destination.addEventListener('change', () => {
    void refreshCity().catch(handleError);
  });
  for (const key of ['type', 'work', 'author', 'relation', 'query']) {
    ui[key].addEventListener(key === 'query' ? 'input' : 'change', () => {
      shownPage = 0;
      render();
      setHash();
    });
  }
  ui.previous.addEventListener('click', () => { if (shownPage) { shownPage--; render(); } });
  ui.next.addEventListener('click', () => { shownPage++; render(); });
})();
